<template><view class="screen"><view class="heading">{{tid?'回复帖子':'发布帖子'}}</view><view class="card"><picker v-if="!tid" :range="forums" range-key="name" @change="fid=forums[Number($event.detail.value)].fid"><view class="choose">{{forums.find(f=>f.fid===fid)?.name||'选择发布版块'}} ›</view></picker><input v-if="!tid" v-model="subject" maxlength="80" placeholder="标题，最多80字"/><view class="toolbar"><text v-for="tool in tools" :key="tool.name" @click="format(tool)">{{tool.name}}</text><text @click="size">字号</text><text @click="color">颜色</text><text @click="insertLink">链接</text><text @click="insertQuote">引用</text><text @click="chooseImage">添加图片</text></view><editor class="editor" placeholder="分享你的内容…" show-img-size @ready="ready" @input="content=$event.detail.html"/><view class="muted">{{uploads.length}} / 9 张图片</view><view v-for="(image,i) in uploads" :key="image.attach_id" class="preview"><image :src="image.url" @click="preview(i)"/><text @click="removeImage(i)">删除图片</text></view><view v-if="error" class="error">{{error}}</view><button :disabled="busy" @click="submit">{{busy?'正在发布…':'发布'}}</button></view></view></template>
<script setup>
import { ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request,post,requireLogin,uploadImage } from '../../api/index.js'
const tid=ref(0),fid=ref(0),forums=ref([]),subject=ref(''),content=ref(''),uploads=ref([]),busy=ref(false),error=ref('');let editor,requestId=Date.now().toString(36)+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)
const tools=[{name:'粗体',key:'bold'},{name:'斜体',key:'italic'},{name:'下划线',key:'underline'},{name:'列表',key:'list',value:'bullet'},{name:'代码',key:'code-block'}]
function ready(){uni.createSelectorQuery().select('.editor').context(r=>{editor=r.context;const q=uni.getStorageSync('zo-quote');if(tid.value&&q){const esc=x=>String(x).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));content.value='<blockquote>'+esc(q.author||'')+'：'+esc(q.message||q.content||'')+'</blockquote><p><br></p>';editor.setContents({html:content.value});uni.removeStorageSync('zo-quote')}}).exec()}
function size(){uni.showActionSheet({itemList:['小号','标准','大号'],success:r=>editor?.format('fontSize',['12px','16px','22px'][r.tapIndex])})}
function color(){uni.showActionSheet({itemList:['默认','蓝色','红色','绿色'],success:r=>editor?.format('color',['#1c1c1e','#007aff','#ff3b30','#34c759'][r.tapIndex])})}
function insertLink(){uni.showModal({title:'插入链接',editable:true,placeholderText:'https://',success:r=>{if(r.confirm&&/^https?:\/\//i.test(r.content))editor?.insertText({text:r.content});else if(r.confirm)uni.showToast({title:'请输入 http 或 https 链接',icon:'none'})}})}
function insertQuote(){uni.showModal({title:'引用内容',editable:true,success:r=>{if(r.confirm)editor?.insertText({text:'\n[quote]'+r.content+'[/quote]\n'})}})}
function preview(i){uni.previewImage({urls:uploads.value.map(x=>x.url),current:i})}
function removeImage(i){const item=uploads.value[i];editor?.getContents({success:r=>{const html=r.html.replace(/<img\b[^>]*>/gi,img=>img.includes(item.url)?'':img);content.value=html;editor.setContents({html});uploads.value.splice(i,1)}})}
function format(t){editor?.format(t.key,t.value)}
function chooseImage(){if(uploads.value.length>=9){uni.showToast({title:'最多9张图片',icon:'none'});return}uni.chooseImage({count:1,success:async r=>{try{busy.value=true;const d=await uploadImage(r.tempFilePaths[0]);uploads.value.push(d);editor?.insertImage({src:d.url});}catch(e){error.value=e.message}finally{busy.value=false}}})}
async function submit(){if(busy.value||!requireLogin())return;busy.value=true;error.value='';try{const d=await post('thread/'+(tid.value?'reply':'post')+'.php',{tid:tid.value,fid:fid.value,subject:subject.value,content_html:content.value,attach_ids:uploads.value.map(x=>x.attach_id),request_id:requestId});uni.showToast({title:d.moderated?'已提交，等待审核':'发布成功',icon:'none'});if(d.moderated)uni.navigateBack();else uni.redirectTo({url:'/pages/thread/detail?tid='+d.tid})}catch(e){error.value=e.message}finally{busy.value=false}}
onLoad(async o=>{if(!requireLogin())return;tid.value=Number(o.tid)||0;fid.value=Number(o.fid)||0;try{forums.value=(await request('forum/list.php')).filter(f=>f.type!=='group')}catch(e){error.value=e.message}})
</script>
<style scoped>.preview{display:flex;align-items:center;gap:20px;margin-top:12px}.preview image{width:80px;height:80px}.preview text{color:#ff3b30}.screen{padding:20px 16px}.heading{font-size:30px;font-weight:800;margin:20px 4px}.choose{padding:12px 0 20px;color:#007aff}input{background:var(--bg)}.toolbar{display:flex;flex-wrap:wrap;gap:18px;padding:18px 0;color:#007aff;font-size:13px}.editor{height:360px;line-height:1.7}button{margin-top:20px}</style>
